SELECT test.assert_true(NOT EXISTS(SELECT FROM public.templates t WHERE NOT EXISTS(SELECT FROM private.model_locations l WHERE l.office_id=t.office_id AND l.template_id=t.id)),'organization: every existing template has a location');
SELECT test.assert_true(NOT EXISTS(SELECT FROM test.organization_locations_before b LEFT JOIN private.model_locations l ON l.office_id=b.office_id AND l.template_id=b.template_id WHERE l.template_id IS NULL OR to_jsonb(l)<>b.snapshot),'organization: manually chosen locations remain unchanged');
SELECT test.assert_true((SELECT templates FROM test.organization_before)=(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY id),'[]'::jsonb) FROM public.templates t) AND(SELECT versions FROM test.organization_before)=(SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY id),'[]'::jsonb) FROM public.template_versions v) AND(SELECT approvals FROM test.organization_before)=(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY office_id,version_id),'[]'::jsonb) FROM private.template_approvals a),'organization: text, versions, authors and approvals preserved');
SELECT test.assert_true(NOT has_table_privilege('authenticated','private.model_folders','INSERT,UPDATE,DELETE') AND NOT has_table_privilege('anon','private.model_locations','SELECT,INSERT,UPDATE,DELETE'),'organization: migration grants no public or client write');
